  function integrationContracts(){const G=window.StegVerseGovernanceIntegration,C=window.StegVerseWorkspaceIntegrationConformance;if(!G||typeof G.validate!=="function"||!C||typeof C.validateDescriptor!=="function"||typeof C.runConformance!=="function"||typeof C.buildIntegrationDraft!=="function"||typeof C.selectMode!=="function"||!Array.isArray(C.FIXTURES))return null;return {G:G,C:C};}
