  function integrationValidationRecord(frameworkId,validation){const valid=validation.descriptor_valid===true;return actionableFor({disposition:"FAIL_CLOSED",predicate:validation.predicate,requested_action:"Validate the "+(frameworkId||"supplied")+" adapter descriptor against the governance integration contract",authority_source:"MANIFEST",consequence_observation:INTEGRATION_OBSERVATION,why:validation.predicate==="INVALID_ADAPTER_DESCRIPTOR_JSON"?"The descriptor text is not valid JSON, so nothing was validated; nothing was submitted or executed.":valid?"The adapter descriptor conforms to stegverse.workspace.governance-integration/v1 (framework-neutral; GitHub is only the reference adapter). Validation is source-only: no manifest was submitted and no authentic manifest-bound governance transition was observed, so the path fails closed by construction. The same contract applies in every integration mode.":"The adapter descriptor failed the governance integration contract on predicate "+String(validation.predicate)+"; nothing was submitted or executed. The same contract applies in every integration mode.",evidence:[{kind:"SOURCE_REF",ref:INTEGRATION_CONTRACT_REF,description:"Framework-neutral governance integration contract (validator source)"}]},valid?"an authentic manifest-bound governance transition for this adapter, submitted through the SDK manifest/InTr route":"an adapter descriptor that conforms to stegverse.workspace.governance-integration/v1",INTEGRATION_CONTRACT_REF+" validate (the WorkSpace developer integration card)","validate a corrected descriptor, or submit the conforming manifest through the governed route; it is decided there and nothing waits");}
  function integrationOutcome(id){const k=integrationContracts();if(!k)return null;if(id==="validation")return state.integrationResult&&state.integrationResult.kind==="validation"&&state.integrationResult.record?state.integrationResult.record:null;const f=k.C.FIXTURES.find(x=>x&&x.id===id);return f&&f.outcome?f.outcome:null;}
