  // status/check predicate is copied verbatim.
  function provenanceEvidence(ref,description){return typeof ref==="string"&&ref.trim()?[{kind:"PROVENANCE_REF",ref:ref,description:description}]:[];}
  // Organization Role conformance item 5 (.github docs/ORGANIZATION_ROLE_RUNTIME_REALITY_DEPLOYMENT.md): every non-ALLOW
  // record carries failure_code, failed_predicate, required_evidence_or_repair, retry_entrypoint, owning_existing_goal and
  // next_attempt. Fields the producer already supplied are kept; the defaults name this page's own entry point.
  const OWNING_GOAL="STEGVERSE-WORKSPACE-ANY-DEVICE-KV-SURFACE-001",ACTIONABLE_KEYS=["failure_code","failed_predicate","required_evidence_or_repair","retry_entrypoint","owning_existing_goal","next_attempt"];
  function actionableFor(r,repair,entry,next){if(!r||r.disposition==="ALLOW")return r;return Object.assign({failure_code:r.predicate,failed_predicate:r.predicate,required_evidence_or_repair:repair,retry_entrypoint:entry,owning_existing_goal:OWNING_GOAL,next_attempt:next},r);}
