  function capabilityOutcome(id){const items=state.statuses;if(!Array.isArray(items))return null;let s=items.find(x=>x&&x.capability===id);if(!s)return null;let notes=[],ref=s.provenance_ref;const P=window.StegVerseWorkspacePanels;if(P&&typeof P.build==="function"&&state.bootstrap){try{const built=P.build({descriptors:state.bootstrap.capability_descriptors,statuses:items,projections:projections(),workspace_type:workspaceType()});const p=built&&built.disposition==="ALLOW"?built.panels.find(x=>x&&x.capability===id):null;if(p){notes=Array.isArray(p.notes)?p.notes.filter(n=>typeof n==="string"&&n.trim()):[];if(p.provenance&&typeof p.provenance.provenance_ref==="string")ref=p.provenance.provenance_ref;if(p.state!==s.state||p.predicate!==s.predicate)s=Object.assign({},s,{state:p.state,predicate:p.predicate});}}catch{}}const reason=decisionReason("CAPABILITY",s.predicate);if(reason)notes.unshift(reason);const r=Object.assign({predicate:typeof s.predicate==="string"&&s.predicate?s.predicate:"CAPABILITY_STATUS_ABSENT",requested_action:"Observe the "+String(s.label||id)+" capability projection in this Workspace",authority_source:"INTERLOCK_INTR"},receiptBacked(s.state==="OBSERVED",ref,"Capability projection provenance (receipt of the KV delivery)","FAIL_CLOSED"));if(notes.length)r.why=notes.join("; ");return actionableFor(r,r.disposition==="UNKNOWN"?"the receipt of the KV delivery this capability rests on; this page holds none":"the producer of the "+String(s.label||id)+" projection supplies an admitted KV projection in which "+r.predicate+" no longer applies","Site assets/workspace-capabilities.js evaluate (the WorkSpace capability card)","the next WorkSpace load evaluates the capability again from the delivered projection; nothing waits");}
  // Plain-language reason for a device-continuity check (DR1-DR5) or a capability status, from the reason catalogs the
